export type BrandSlug = keyof typeof BRANDS;

type BrandLogoStyle = React.CSSProperties & { '--brand': string };

export type BrandLogoProps = {
  brand: BrandSlug;
  className?: string;
  /** The accessible name. Without it the mark is decorative and hidden from assistive technology. */
  title?: string;
};

function colourClassOf(brand: Brand) {
  if (brand.tooDarkOnDark) {
    return 'text-(--brand) dark:text-foreground';
  }
  return 'text-(--brand)';
}

function roleOf(isNamed: boolean) {
  if (isNamed) {
    return 'img';
  }
  return undefined;
}

function hiddenOf(isNamed: boolean) {
  if (isNamed) {
    return undefined;
  }
  return true;
}

export function BrandLogo({ brand, className, title }: BrandLogoProps) {
  const data: Brand = BRANDS[brand];
  const style: BrandLogoStyle = { '--brand': data.hex };
  const isNamed = Boolean(title);

  return (
    <svg
      viewBox='0 0 24 24'
      fill='currentColor'
      focusable='false'
      role={roleOf(isNamed)}
      aria-label={title}
      aria-hidden={hiddenOf(isNamed)}
      style={style}
      className={cn('size-4 shrink-0', colourClassOf(data), className)}
    >
      <path d={data.path} />
    </svg>
  );
}
